// Parse AI output
const rawOutput = $input.first().json.output || $input.first().json.text || $input.first().json;
let parsedData;

try {
  if (typeof rawOutput === 'string') {
    const cleaned = rawOutput.replace(/```json/g, '').replace(/```/g, '').trim();
    parsedData = JSON.parse(cleaned);
  } else {
    parsedData = rawOutput;
  }
} catch (e) {
  parsedData = {
    client_name: "VIP Guest",
    destination: "Amalfi Coast",
    pax_adults: 2,
    pax_children: 0,
    travel_start_date: "2026-09-20",
    travel_end_date: "2026-09-24",
    service_tier: "Luxury",
    special_requests: "Automated fallback parsing"
  };
}

// Generate unique inquiry ID
const inquiryId = 'INQ-' + new Date().getFullYear() + '-' + Math.floor(1000 + Math.random() * 9000);

// Sample Mock Tariff Catalog for auto-costing
const sampleCatalog = [
  { keyword: "transfer", unit_net: 180, title: "Private Mercedes Transfer", supplier_id: "SUP-TRN-001" },
  { keyword: "hotel", unit_net: 620, title: "5-Star Luxury Sea View Suite", supplier_id: "SUP-HTL-002" },
  { keyword: "guide", unit_net: 280, title: "Private Licensed Local Expert Guide (3h)", supplier_id: "SUP-GDE-001" },
  { keyword: "boat", unit_net: 1900, title: "Private Yacht Charter with Skipper & Prosecco", supplier_id: "SUP-ACT-001" }
];

const items = [];
let totalNetCost = 0;
const days = parsedData.duration_days || 4;

for (let day = 1; day <= days; day++) {
  let matchedTariff;
  if (day === 1) {
    matchedTariff = sampleCatalog.find(c => c.keyword === 'transfer');
  } else if (day === 2) {
    matchedTariff = sampleCatalog.find(c => c.keyword === 'guide');
  } else if (day === 3) {
    matchedTariff = sampleCatalog.find(c => c.keyword === 'boat');
  } else {
    matchedTariff = sampleCatalog.find(c => c.keyword === 'transfer');
  }

  const netCost = matchedTariff.unit_net;
  totalNetCost += netCost;

  items.push({
    day_number: day,
    service_title: matchedTariff.title,
    service_type: day === 1 || day === days ? "Private Transport" : "Excursion",
    service_description: `VIP tailored service for ${parsedData.pax_adults} guests in ${parsedData.destination}.`,
    supplier_id: matchedTariff.supplier_id,
    net_cost: netCost
  });
}

// Calculate DMC Profit Margin (22% standard)
const marginPercent = 0.22;
const grossSellingPrice = Math.round(totalNetCost / (1 - marginPercent));

return [{
  json: {
    inquiry_id: inquiryId,
    client_name: parsedData.client_name,
    client_email: parsedData.client_email,
    destination: parsedData.destination,
    travel_start_date: parsedData.travel_start_date,
    travel_end_date: parsedData.travel_end_date,
    pax_adults: parsedData.pax_adults,
    pax_children: parsedData.pax_children || 0,
    service_tier: parsedData.service_tier,
    special_requests: parsedData.special_requests,
    currency: "EUR",
    total_net_cost: totalNetCost,
    margin_percent: "22%",
    gross_selling_price: grossSellingPrice,
    itinerary_items: items
  }
}];

const data = $input.first().json;

let itemsHtml = '';
data.itinerary_items.forEach(item => {
  itemsHtml += `
    <div style="border: 1px solid #E2E8F0; border-radius: 8px; padding: 18px; margin-bottom: 16px; background: #FFF;">
      <div style="font-size: 12px; font-weight: 700; color: #C5A059; text-transform: uppercase;">Day ${item.day_number}</div>
      <h3 style="margin: 6px 0; font-size: 16px; color: #1A365D;">${item.service_title}</h3>
      <p style="color: #4A5568; font-size: 14px; margin-bottom: 8px;">${item.service_description}</p>
      <span style="background: #EDF2F7; font-size: 11px; padding: 3px 8px; border-radius: 4px; color: #4A5568;">${item.service_type}</span>
    </div>
  `;
});

const proposalHtml = `
<!DOCTYPE html>
<html>
<head><meta charset="utf-8"><title>Proposal ${data.inquiry_id}</title></head>
<body style="font-family: sans-serif; background: #F7FAFC; padding: 30px; margin: 0;">
  <div style="max-width: 720px; margin: 0 auto; background: #FFF; border-radius: 8px; overflow: hidden; border: 1px solid #E2E8F0;">
    <div style="background: #1A365D; color: #FFF; padding: 40px;">
      <div style="color: #C5A059; font-weight: bold; font-size: 12px; letter-spacing: 2px;">BESPOKE DMC PROPOSAL</div>
      <h1 style="margin: 10px 0 6px 0;">${data.destination}</h1>
      <div>Prepared exclusively for: <strong>${data.client_name}</strong></div>
    </div>
    <div style="padding: 30px;">
      <h2 style="color: #1A365D; font-size: 18px; border-bottom: 2px solid #C5A059; padding-bottom: 8px;">Daily Schedule</h2>
      ${itemsHtml}
      <div style="background: #F8FAFC; border: 1px solid #E2E8F0; padding: 24px; border-radius: 8px; margin-top: 24px; text-align: right;">
        <div style="font-size: 13px; color: #718096;">Total Investment (${data.pax_adults} Guests)</div>
        <div style="font-size: 28px; font-weight: bold; color: #1A365D;">${data.currency} ${data.gross_selling_price.toLocaleString()}</div>
        <div style="font-size: 11px; color: #A0AEC0;">Includes all ground transport, private guide, charters, taxes & VIP concierge.</div>
      </div>
    </div>
  </div>
</body>
</html>
`;

return [{
  json: {
    ...data,
    rendered_html: proposalHtml
  }
}];
